          { label: { en: 'Look and feel', he: 'עיצוב' }, text: { en: 'Design: clean, friendly, large buttons, works well on mobile, Hebrew and English labels.', he: 'עיצוב: נקי וידידותי, כפתורים גדולים, עובד טוב בטלפון, תוויות בעברית ובאנגלית.' } },
          { label: { en: 'Output', he: 'תוצאה' }, text: { en: 'Show the total live as the user changes options, a breakdown of the price, and a “Send to WhatsApp” button with the summary.', he: 'מציגים את הסכום בזמן אמת כשמשנים אפשרויות, פירוט של המחיר, וכפתור "שליחה לוואטסאפ" עם הסיכום.' } },
          { label: { en: 'Limits', he: 'גבולות' }, text: { en: 'Show “Estimate only — final price after a visit.” Do not collect personal details.', he: 'להציג "הערכה בלבד — מחיר סופי אחרי ביקור." לא לאסוף פרטים אישיים.' } }
